--[====[
Preserved inactive research: Data/Expansions/BurningCrusade/QuestRoutes.lua
This material is retained for reference and does not register character quest routes.

-- Burning Crusade catalogue bucket; quest data and map IDs are Retail only.
local _,TDP=...
local guides,routes=TDP.CollectionWalkthroughs,TDP.CollectionQuestRoutes
local data=TDP.BurningCrusadeQuestData
local function point(mapID,x,y) return {mapID=mapID,x=x/100,y=y/100} end
local function step(id,overrides)
    local original=data.quests[id]
    if not original then return nil end
    local copy={}
    for key,value in pairs(original) do copy[key]=value end
    for key,value in pairs(overrides or {}) do copy[key]=value end
    return copy
end
local function register(key,name,ends,options)
    local route=options or {}
    local quests,seen,visiting={},{},{}
    local optional={}
    for _,id in ipairs(route.optionalQuestIDs or {}) do optional[id]=true end
    local function visit(id)
        if seen[id] or visiting[id] then return end
        local quest=data.quests[id]
        if not quest then return end
        visiting[id]=true
        for _,previous in ipairs(quest.requires or {}) do visit(previous) end
        visiting[id],seen[id]=nil,true
        quests[#quests+1]=optional[id] and step(id,{optional=true}) or quest
    end
    for _,id in ipairs(ends) do visit(id) end
    route.key,route.name,route.quests,route.version=key,name,quests,1
    route.reviewedAt,route.sourceRevision=data.reviewedAt,data.revision
    routes[key]=route
    return route
end
local function attach(kind,ids,route,keepPins)
    if not route then return end
    for _,id in ipairs(ids) do
        local guide=guides[kind] and guides[kind][id]
        if guide then
            guide.questRoutes=guide.questRoutes or {}
            local exists=false
            for _,current in ipairs(guide.questRoutes) do if current.key==route.key then exists=true; break end end
            if not exists then guide.questRoutes[#guide.questRoutes+1]=route end
            if keepPins then guide.keepReferencePins=true end
        end
    end
end
local function repeating(ids)
    local result={}
    for _,id in ipairs(ids) do result[#result+1]=step(id) end
    return result
end

