    local route=register("bc-daily-"..entry.achievementID.."-"..entry.criteriaID,entry.name,{}, {
        compact=true,achievementID=entry.achievementID,criteriaID=entry.criteriaID,
        repeatableRewards=true,repeatableQuests={step(entry.questID)},
        after="The achievement criterion is read separately from daily quest flags. Check the giver's actual offer; missing dailies can require later daily resets.",
    })
    attach("achievements",{entry.achievementID},route,true)
end

-- Account-wide pet-tamer ACCESS is an explicit exception. Account unlocks are
-- displayed separately and never become this character's completed quest flags.
local tamers=register("bc-pet-tamer-outland","Pet-tamer access - first trainers to Antari",{31920},{
    accountWide=true,endQuestID=31920,
    after="Battle Pet Training is learned from the capital pet trainer. Earlier continent tamer quests unlock Outland for the account. Defeat the four Outland tamers, hand in to Audrey/Varzok, then finish Grand Master Antari. Account access credit is separate from personal quest history."})
attach("achievements",{6604},tamers,true)

-- Current Retail chapter IDs determine credited status. Every constituent
-- endpoint contributes its prerequisite tree; an arbitrary single subquest
-- completion never marks a whole chapter done.
for _,entry in ipairs(data.chapters) do
    local route=register("bc-story-"..entry.achievementID.."-"..entry.criteriaID,
        entry.zoneName.." - "..entry.name,entry.ends,{
            faction=entry.faction,compact=true,achievementID=entry.achievementID,criteriaID=entry.criteriaID,
            sourceURL="https://www.wowhead.com/achievement="..entry.achievementID,
        })
    attach("achievements",{entry.achievementID,1262},route)
end

-- Ghostlands and Bloodmyst guides already share the Classic audit's Retail
-- story routes. Remaining entries use vendors, drops, capture, professions,
-- exploration or PvP; retired raid keys and class-mount chains are not added.

